"""Independent reference for FAPIgo's pairwise.NewReversible.

Synthetic IV with Python's stdlib hmac/hashlib; AES-256-CTR with the
OpenSSL command-line tool (a separate C implementation from Go's
crypto/aes). Prints pairwise/testdata/reversible_vectors.json.
"""
import base64, hashlib, hmac, json, struct, subprocess

DOMAIN = b"fapigo ppid r1"
MAX_SUBJECT = 151
PLAIN_LEN = 1 + MAX_SUBJECT

def lp(field: bytes) -> bytes:
    return struct.pack(">I", len(field)) + field

def plaintext(subject: bytes) -> bytes:
    assert 1 <= len(subject) <= MAX_SUBJECT
    return bytes([len(subject)]) + subject + b"\x00" * (PLAIN_LEN - 1 - len(subject))

def aes256ctr_openssl(key: bytes, iv: bytes, data: bytes) -> bytes:
    out = subprocess.run(
        ["openssl", "enc", "-aes-256-ctr", "-nosalt", "-nopad", "-K", key.hex(), "-iv", iv.hex()],
        input=data, capture_output=True, check=True)
    return out.stdout

def derive(mac_key, enc_key, issuer, sector, subject):
    a = lp(DOMAIN) + lp(issuer.encode()) + lp(sector.encode())
    p = plaintext(subject.encode())
    iv = hmac.new(mac_key, a + p, hashlib.sha256).digest()[:16]
    c = aes256ctr_openssl(enc_key, iv, p)
    assert len(c) == PLAIN_LEN
    return base64.urlsafe_b64encode(iv + c).rstrip(b"=").decode()

mac_key = bytes(range(0, 32))
enc_key = bytes(range(32, 64))
other_mac = bytes(range(64, 96))
other_enc = bytes(range(96, 128))
cases = [
    (mac_key, enc_key, "https://op.example", "rp.example", "user-1"),
    (mac_key, enc_key, "https://op.example", "rp.example", "user-2"),
    (mac_key, enc_key, "https://op.example", "other.example", "user-1"),
    (mac_key, enc_key, "https://other-op.example", "rp.example", "user-1"),
    (mac_key, enc_key, "https://op.example", "rp.example", "u"),
    (mac_key, enc_key, "https://op.example", "rp.example", "user with spaces ~!"),
    (mac_key, enc_key, "https://op.example", "rp.example", "x" * 151),
    (mac_key, enc_key, "https://op.example/tenant/7", "app.bank.example", "0123456789"),
    (other_mac, other_enc, "https://op.example", "rp.example", "user-1"),
]
vectors = [{"mac_key": m.hex(), "enc_key": e.hex(), "issuer": i, "sector": s, "subject": u,
            "body": derive(m, e, i, s, u)} for (m, e, i, s, u) in cases]
print(json.dumps({
    "construction": "SIV: A = u32be(len(f)) || f for f in [\"fapigo ppid r1\", issuer, sector]; "
                    "P = byte(len(subject)) || subject || zero padding to 152 bytes; "
                    "IV = HMAC-SHA-256(mac_key, A || P)[:16]; C = AES-256-CTR(enc_key, IV, P); "
                    "body = base64url(IV || C) without padding",
    "provenance": "generated by an independent reference: Python stdlib hmac/hashlib for the IV, "
                  "the OpenSSL command-line tool for AES-256-CTR",
    "vectors": vectors}, indent=2))
